/**
 * TACTO interface text in Spanish and English.
 *
 * lang-boot.js chooses the page language before the styles and modules load
 * (?lang= in the address, then a saved choice, then the browser languages) and
 * writes it to <html lang>. The language stays fixed for the life of the page:
 * chooseLanguage() stores the new choice and reloads.
 *
 * Outside a browser (tests, narration scripts) the default is Spanish.
 * Lesson content lives with each scene in scenes.js.
 */
