/** Return 'es' or 'en' for a language tag such as "en-GB", otherwise null. */
export function normalizeLanguage(value) {
  if (typeof value !== 'string') return null;
  const code = value.trim().toLowerCase().split(/[-_]/)[0];
  return LANGUAGES.includes(code) ? code : null;
}

let current = normalizeLanguage(globalThis.document?.documentElement?.lang) ?? DEFAULT_LANGUAGE;

export function getLanguage() { return current; }

/** For tests and scripts. In the page, use chooseLanguage(), which reloads. */
export function setLanguage(language) {
  current = normalizeLanguage(language) ?? DEFAULT_LANGUAGE;
  return current;
}

export function translate(language, key, params = {}) {
  const table = messages[normalizeLanguage(language) ?? DEFAULT_LANGUAGE];
  const template = Object.hasOwn(table, key) ? table[key]
    : Object.hasOwn(messages[DEFAULT_LANGUAGE], key) ? messages[DEFAULT_LANGUAGE][key] : key;
  return template.replace(/\{(\w+)\}/g, (match, name) => (
    params && Object.hasOwn(params, name) ? String(params[name]) : match
  ));
}

export function t(key, params) { return translate(current, key, params); }

/** Messages with a count use the keys "<key>.one" and "<key>.other". */
export function plural(key, count, params = {}) {
  return t(`${key}.${count === 1 ? 'one' : 'other'}`, { ...params, count });
}

/** BCP 47 locale for speech in the given language. */
export function speechLocale(language = current) {
  return SPEECH_LOCALES[normalizeLanguage(language) ?? DEFAULT_LANGUAGE];
}

/** Keys defined for a language; used by the tests to compare both dictionaries. */
export function messageKeys(language) {
  return Object.keys(messages[normalizeLanguage(language) ?? DEFAULT_LANGUAGE]);
}

/**
 * Fill static markup: data-i18n sets text, data-i18n-html sets trusted markup
 * from this file, and data-i18n-attr="aria-label:key;title:key" sets attributes.
 */
export function applyTranslations(root = globalThis.document) {
  if (typeof root?.querySelectorAll !== 'function') return;
  for (const element of root.querySelectorAll('[data-i18n]')) element.textContent = t(element.dataset.i18n);
  for (const element of root.querySelectorAll('[data-i18n-html]')) element.innerHTML = t(element.dataset.i18nHtml);
  for (const element of root.querySelectorAll('[data-i18n-attr]')) {
    for (const pair of element.dataset.i18nAttr.split(';')) {
      const [attribute, key] = pair.split(':').map(part => part.trim());
      if (attribute && key) element.setAttribute(attribute, t(key));
    }
  }
}

/**
 * Remember a language and reload the page in it. An address that already names
 * a language (?lang=… or #es/#en) is updated to the new one. When the choice
 * cannot be stored, the hash carries it: it survives the reload on any host,
 * including those that drop the query string. Returns false when nothing changes.
 */
export function chooseLanguage(language, { location = globalThis.location, storage } = {}) {
  const next = normalizeLanguage(language);
  if (!next || next === current || !location) return false;
  let remembered = false;
  try {
    const store = storage ?? globalThis.localStorage;
    store.setItem(LANGUAGE_STORAGE_KEY, next);
    remembered = store.getItem(LANGUAGE_STORAGE_KEY) === next;
  } catch { /* Private browsing or blocked storage: use the hash instead. */ }
  const url = new URL(location.href);
  if (url.searchParams.has('lang')) {
    url.searchParams.set('lang', next);
    location.replace(url.href);
    return true;
  }
  if (!remembered || /^#(es|en)$/i.test(url.hash)) location.hash = next;
  location.reload();
  return true;
}
